  H[5] = 2.828427124746191*theta[0]*G_1[5]-1.264911064067352*theta_sq[2]*F_0[5]-1.4142135623730951*theta_sq[0]*F_0[5]+2.8284271247461907*theta[1]*G_1[4]-1.4142135623730951*theta_sq[1]*F_0[4]; 
  H[6] = -(1.4142135623730951*F_0[0]*theta_sq[2])-1.264911064067352*F_0[1]*theta_sq[1]+2.5298221281347044*G_1[1]*theta[1]; 
  H[7] = 2.5298221281347044*theta[1]*G_1[3]-1.264911064067352*theta_sq[1]*F_0[3]-1.4142135623730951*F_0[2]*theta_sq[2]; 
